package com.snipsnap.synth

import com.snipsnap.audio.Pitch
import com.snipsnap.audio.Snip
import com.snipsnap.audio.WavWriter
import java.io.ByteArrayOutputStream
import java.security.MessageDigest
import kotlin.math.abs
import kotlin.math.ln
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/** Sound fixtures selected by the owner's 2026-10-24 listening export, not generated by these tests. */
class MurmurApprovedCandidatesTest {
    private data class Fixture(
        val voice: MurmurVoice, val midi: Int, val motion: Float, val held: Boolean,
        val frames: Int, val rawHash: String, val matchedHash: String,
    )

    @Test
    fun `new saved patches reproduce all twelve WAVs chosen in the listening review`() {
        // Published at 7b17c3441; the export identifies these six candidate cases and their
        // native/matched hashes. Check encoded audio as well as saved patch replay.
        val fixtures = listOf(
            Fixture(MurmurVoice.KEY, 60, 0f, false, 132300,
                "2dd9a7bdb1f6b277e6612c8b14919531d7b34b825d54aac3ad93ee2eb8d39d3e",
                "6c60f45be9fb3ae67dbaf269061897bdfc71be54bc6ffcf89202babcef86f88e"),
            Fixture(MurmurVoice.KEY, 60, .5f, false, 132300,
                "1d53370aba8929b7fecec3afa3efa2fd3b9a2b1f0dd6c8d6019b4456c0a962dd",
                "89c45f7bf1c7112b189e77911a443a9099fd12b98235bf8dccaa956f9cdf9545"),
            Fixture(MurmurVoice.KEY, 60, .75f, false, 132300,
                "6cf915ab706716b24852939692d55d58abc3f5dbd69db11137e28c83fcf46e69",
                "569b35b1d995b96d5d8085f5c1b34270c5980604df50eaf16d4e04a3fff2685a"),
            Fixture(MurmurVoice.KEY, 60, 1f, false, 132300,
                "a8e2454f559a7d53684d238063c1990d2dc9c905bb2a44497bcad158c67394f7",
                "3cfe9450e58f9aca9334ecc32d3da69a38c7835836c5fe40383cc4ec0cfd1d7b"),
            Fixture(MurmurVoice.CHOIR, 36, .3f, true, 225200,
                "737cde38826cab81b5b5cdff9e1f72ec757c9a591888433e0a985353603797c7",
                "311c1aad3a5c5827710be209bc330ce840cf5ab39bdacf7410f73435084e7e06"),
            Fixture(MurmurVoice.CHOIR, 48, .3f, true, 112592,
                "4c814db899f7cc6851d0603b1df49527b7a578cefbc626b8f6e3838586668ad1",
                "284a74f9b3361cbf7f60c4b67771e1c1af26ee2ee558bdc21d01b6587e54b676"),
        )
        for (fixture in fixtures) {
            val macros = Murmur.defaults(fixture.voice) + mapOf(
                "MOTION" to fixture.motion, "HOLD" to if (fixture.held) 1f else 0f,
            )
            val patch = MurmurPatch("Owner selected candidate", fixture.voice, macros, fixture.midi)
            assertEquals(3, patch.config.model)
            val restored = MurmurPatch.fromJsonText(patch.toJsonText())
            assertEquals(patch, restored)
            val raw = Murmur.renderRaw(restored.voice, restored.macros, restored.midi, restored.velocity, restored.config)
            assertEquals(fixture.frames, raw.size, "${fixture.voice} MIDI ${fixture.midi} MOTION ${fixture.motion}")
            val native = Snip(raw, 1, Dsp.RATE)
            assertEquals(fixture.rawHash, wavHash(native), "${fixture.voice} selected native WAV changed")
            assertEquals(fixture.matchedHash, wavHash(AuditionLevel.level(native)),
                "${fixture.voice} selected matched WAV changed")
            assertContentEquals(raw, Murmur.renderRaw(patch.voice, patch.macros, patch.midi, patch.velocity, patch.config),
                "${fixture.voice} saved candidate is not deterministic")
        }
    }

    @Test
    fun `the promoted low choir remains pitched bounded and seamless between the two heard notes`() {
        val macros = Murmur.defaults(MurmurVoice.CHOIR) + ("HOLD" to 1f)
        for (midi in 36..48) {
            val probe = Murmur.probe(MurmurVoice.CHOIR, macros, midi)
            val seconds = probe.samples.size / Dsp.RATE.toDouble()
            assertTrue(seconds in 1.8..Murmur.MAX_SECONDS, "MIDI $midi has an unbounded or too-short loop: $seconds")
            assertEquals(0, probe.samples.size % 16, "MIDI $midi loses its whole control-block period")
            assertEquals(probe.samples.size, probe.previousCycle.size)
            assertTrue(probe.samples.all { it.isFinite() }, "MIDI $midi has non-finite PCM")
            assertTrue(probe.samples.maxOf { abs(it) } < 1f, "MIDI $midi clips its raw audition")
            assertTrue(probe.samples.any { abs(it) > .001f }, "MIDI $midi closes its loop by becoming silent")
            val root = Keys.midiHz(midi).toDouble()
            val plannedCents = 1200.0 * ln(probe.rootHz / root) / ln(2.0)
            assertTrue(abs(plannedCents) < 1.0, "MIDI $midi planned root moved $plannedCents cents")
            val pitch = assertNotNull(Pitch.detect(Snip(probe.samples, 1, Dsp.RATE), fromSec = .1f),
                "MIDI $midi has no measured root")
            val measuredCents = 1200.0 * ln(pitch.hz / root) / ln(2.0)
            println("MURMUR APPROVED CHOIR MIDI $midi: duration $seconds, pitch $measuredCents cents, confidence ${pitch.confidence}, seam ${probe.seamError}")
            assertTrue(abs(measuredCents) < 8.0, "MIDI $midi measured root moved $measuredCents cents")
            assertTrue(pitch.confidence > .6f, "MIDI $midi root confidence is ${pitch.confidence}")
            val seam = Keys.seamError(probe.previousCycle + probe.samples, probe.previousCycle.size)
            assertEquals(probe.seamError, seam)
            assertTrue(seam.isFinite() && seam < Keys.MAX_SEAM_ERROR, "MIDI $midi does not meet its independent continuation: $seam")
        }
    }

    @Test
    fun `the promoted policy leaves higher choir notes finite choir and the other four roles unchanged`() {
        for (midi in listOf(49, 60, 96)) {
            val macros = Murmur.defaults(MurmurVoice.CHOIR) + ("HOLD" to 1f)
            assertContentEquals(
                Murmur.renderRaw(MurmurVoice.CHOIR, macros, midi, config = Murmur.configurationFor(MurmurVoice.CHOIR, 2)),
                Murmur.renderRaw(MurmurVoice.CHOIR, macros, midi, config = Murmur.configurationFor(MurmurVoice.CHOIR, 3)),
                "unheard upper CHOIR MIDI $midi changed",
            )
        }
        for (midi in listOf(36, 48)) {
            assertContentEquals(
                Murmur.renderRaw(MurmurVoice.CHOIR, midi = midi, config = Murmur.configurationFor(MurmurVoice.CHOIR, 2)),
                Murmur.renderRaw(MurmurVoice.CHOIR, midi = midi, config = Murmur.configurationFor(MurmurVoice.CHOIR, 3)),
                "finite CHOIR MIDI $midi changed outside the held-loop policy",
            )
        }
        for (voice in listOf(MurmurVoice.BASS, MurmurVoice.PLUCK, MurmurVoice.LEAD, MurmurVoice.METAL)) {
            for (held in listOf(0f, 1f)) {
                val macros = Murmur.defaults(voice) + ("HOLD" to held)
                assertContentEquals(
                    Murmur.renderRaw(voice, macros, config = Murmur.configurationFor(voice, 2)),
                    Murmur.renderRaw(voice, macros, config = Murmur.configurationFor(voice, 3)),
                    "$voice HOLD $held changed without a new owner selection",
                )
            }
        }
    }

    @Test
    fun `custom choir detunes that cannot make a bounded beat period retain the short loop`() {
        for (lastRatio in listOf(1.0, 1.00001, 1.01)) {
            val original = Murmur.configurationFor(MurmurVoice.CHOIR, 2)
                .copy(ratios = listOf(1.0, 1.0, 2.0, lastRatio))
            val macros = Murmur.defaults(MurmurVoice.CHOIR) + ("HOLD" to 1f)
            assertContentEquals(
                Murmur.renderRaw(MurmurVoice.CHOIR, macros, 36, config = original),
                Murmur.renderRaw(MurmurVoice.CHOIR, macros, 36, config = original.copy(model = 3)),
                "custom fourth ratio $lastRatio should retain the bounded short-loop fallback",
            )
        }
    }

    private fun wavHash(snip: Snip): String {
        val bytes = ByteArrayOutputStream().also { WavWriter.write(it, snip, WavWriter.BitDepth.PCM_24) }.toByteArray()
        return MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }
    }
}
